export function mergeIntervals(intervals) {
 if (!Array.isArray(intervals) || intervals.some(x => !Array.isArray(x) || x.length !== 2 || !x.every(Number.isFinite) || x[0] > x[1])) throw new TypeError('invalid');
 const sorted = intervals.map(x => [...x]).sort((a,b) => a[0]-b[0]);
 const out = [];
 for (const x of sorted) { const last = out[out.length-1]; if (last && x[0] <= last[1]) last[1] = Math.max(last[1],x[1]); else out.push(x); }
 return out;
}

